from taf.gnb.oam.coam.vdu.releases.vduoam21b import vDuOAM21B
from taf.gnb.oam.coam.vdu.schemas.asm.managed_object_parameters import (
    ManagedObjectParameters,
)
from taf.gnb.oam.coam.vdu.schemas.cp_config.get_prach_test_results import (
    GetPrachCPCONFIGV1,
)
from taf.gnb.oam.coam.vdu.schemas.cp_config.get_pucch_test_results import (
    GetPucchCPCONFIGV1,
)
from taf.gnb.oam.coam.vdu.schemas.cp_config.get_pusch_test_results import (
    GetPuschCPCONFIGV1,
)
from taf.gnb.oam.coam.vdu.schemas.cp_config.get_running_test_models import (
    GetRunningTestModelsCPCONFIGV1,
)
from taf.gnb.oam.coam.vdu.schemas.cp_config.get_uplink_test_results import (
    GetUplinkCPCONFIGV1,
)


class vDuOAM22R2(vDuOAM21B):
    def start_5g_downlink_test(self, nrcell_id, test_model, beam_pattern_id, polarization, power_backoff, ru_mode,
                               phys_cell_id, codebook_2_antports, i11_codebook_4_antports, i2_codebook_4_antports,
                               i13_codebook_4_antports, mimo_rank, p_max, nrarfcn, timeout=60, nrarfcn_ul=0, nrarfcn_dl=0,
                               **kwargs):
        return self.cp_config.start_5g_downlink_test(nrcell_id=nrcell_id,
                                                     test_model=test_model,
                                                     beam_pattern_id=beam_pattern_id,
                                                     polarization=polarization,
                                                     power_backoff=power_backoff,
                                                     ru_mode=ru_mode,
                                                     phys_cell_id=phys_cell_id,
                                                     codebook_2_antports=codebook_2_antports,
                                                     i11_codebook_4_antports=i11_codebook_4_antports,
                                                     i2_codebook_4_antports=i2_codebook_4_antports,
                                                     i13_codebook_4_antports=i13_codebook_4_antports,
                                                     mimo_rank=mimo_rank,
                                                     p_max=p_max,
                                                     nrarfcn=nrarfcn,
                                                     nrarfcn_ul=nrarfcn_ul,
                                                     nrarfcn_dl=nrarfcn_dl,
                                                     timeout=timeout)

    def stop_5g_downlink_test(self, nrcell_id, timeout):
        return self.cp_config.stop_5g_downlink_test(nrcell_id=nrcell_id, timeout=timeout)

    def start_5g_uplink_test(self, nrcell_id, frc_index, beam_pattern_id, interval, prb_offset, ru_mode, phys_cell_id,
                             nrarfcn=0, timeout=60, nrarfcn_ul=0, nrarfcn_dl=0):
        return self.cp_config.start_5g_uplink_test(nrcell_id=nrcell_id,
                                                   frc_index=frc_index,
                                                   beam_pattern_id=beam_pattern_id,
                                                   interval=interval,
                                                   prb_offset=prb_offset,
                                                   ru_mode=ru_mode,
                                                   phys_cell_id=phys_cell_id,
                                                   nrarfcn=nrarfcn,
                                                   timeout=timeout,
                                                   nrarfcn_ul=nrarfcn_ul,
                                                   nrarfcn_dl=nrarfcn_dl)

    def stop_5g_uplink_test(self, nrcell_id, timeout=60):
        return self.cp_config.stop_5g_uplink_test(nrcell_id=nrcell_id, timeout=timeout)

    def start_5g_uplink_ccm_test_pusch(self, nrcell_id, interval, beam_pattern_id, frc_index, prb_offset,
                                       digital_out_type, digital_out_rate, ru_mode, phys_cell_id, ul_dmrs_mapping_type,
                                       nrarfcn, num_uci_bits, csi_payload_bit, timeout=60, bb_selector=0,
                                       nrarfcn_ul=0, nrarfcn_dl=0, digital_output_enable=False,
                                       act_high_speed_cell=False):
        return self.cp_config.start_5g_uplink_ccm_test_pusch(nrcell_id=nrcell_id,
                                                             interval=interval,
                                                             beam_pattern_id=beam_pattern_id,
                                                             frc_index=frc_index,
                                                             prb_offset=prb_offset,
                                                             digital_out_type=digital_out_type,
                                                             digital_out_rate=digital_out_rate,
                                                             ru_mode=ru_mode,
                                                             phys_cell_id=phys_cell_id,
                                                             bb_selector=bb_selector,
                                                             nrarfcn=nrarfcn,
                                                             ul_dmrs_mapping_type=ul_dmrs_mapping_type,
                                                             num_uci_bits=num_uci_bits,
                                                             csi_payload_bit=csi_payload_bit,
                                                             nrarfcn_ul=nrarfcn_ul,
                                                             nrarfcn_dl=nrarfcn_dl,
                                                             digital_output_enable=digital_output_enable,
                                                             act_high_speed_cell=act_high_speed_cell,
                                                             timeout=timeout)

    def start_5g_uplink_ccm_test_pucch(self, nrcell_id, interval, beam_pattern_id, receiving_slot, expectation_slot,
                                       pucch_format, ru_mode, phys_cell_id, format3_additional_dmrs, prb_offset,
                                       largest_prb_index, num_pucch_symbol, num_payload_bit, pucch_payload_content,
                                       nrarfcn, timeout=60, nrarfcn_ul=0, nrarfcn_dl=0, **kwargs):
        return self.cp_config.start_5g_uplink_ccm_test_pucch(nrcell_id=nrcell_id,
                                                             interval=interval,
                                                             beam_pattern_id=beam_pattern_id,
                                                             receiving_slot=receiving_slot,
                                                             expectation_slot=expectation_slot,
                                                             pucch_format=pucch_format,
                                                             ru_mode=ru_mode,
                                                             phys_cell_id=phys_cell_id,
                                                             nrarfcn=nrarfcn,
                                                             prb_offset=prb_offset,
                                                             largest_prb_index=largest_prb_index,
                                                             num_pucch_symbol=num_pucch_symbol,
                                                             num_payload_bit=num_payload_bit,
                                                             pucch_payload_content=pucch_payload_content,
                                                             format3_additional_dmrs=format3_additional_dmrs,
                                                             timeout=timeout,
                                                             nrarfcn_ul=nrarfcn_ul,
                                                             nrarfcn_dl=nrarfcn_dl,
                                                             **kwargs)

    def start_5g_uplink_ccm_test_prach(self, nrcell_id, interval, beam_pattern_id, receiving_slot,
                                       expectation_slot, preamble_index, accepted_timing_error,
                                       constant_offset, delay_pattern_single_step_duration,
                                       ru_mode, phys_cell_id, prach_configuration_index, pfa_target_prach_id,
                                       prach_root_sequence_index, nrarfcn, zero_correlation_zone_config,
                                       timeout=60, nrarfcn_ul=0, nrarfcn_dl=0, prach_sequence_type="Unrestricted"):
        return self.cp_config.start_5g_uplink_ccm_test_prach(nrcell_id=nrcell_id,
                                                             interval=interval,
                                                             beam_pattern_id=beam_pattern_id,
                                                             receiving_slot=receiving_slot,
                                                             expectation_slot=expectation_slot,
                                                             preamble_index=preamble_index,
                                                             accepted_timing_error=accepted_timing_error,
                                                             constant_offset=constant_offset,
                                                             delay_pattern_single_step_duration=delay_pattern_single_step_duration,
                                                             ru_mode=ru_mode,
                                                             phys_cell_id=phys_cell_id,
                                                             prach_configuration_index=prach_configuration_index,
                                                             pfa_target_prach_id=pfa_target_prach_id,
                                                             prach_root_sequence_index=prach_root_sequence_index,
                                                             nrarfcn=nrarfcn,
                                                             zero_correlation_zone_config=zero_correlation_zone_config,
                                                             nrarfcn_ul=nrarfcn_ul,
                                                             nrarfcn_dl=nrarfcn_dl,
                                                             prach_sequence_type=prach_sequence_type,
                                                             timeout=timeout)

    def stop_5g_uplink_ccm_test(self, nrcell_id, timeout=60):
        return self.cp_config.stop_5g_uplink_ccm_test(nrcell_id=nrcell_id, timeout=timeout)

    def get_5g_uplink_test_results(self, nrcell_id, timeout=60, raw=False):
        res = self.cp_config.get_5g_uplink_test_results(nrcell_id=nrcell_id, timeout=timeout)
        return res if raw else GetUplinkCPCONFIGV1.from_object_dict(res)

    def get_5g_pusch_test_results(self, nrcell_id, timeout=60, raw=False):
        res = self.cp_config.get_5g_pusch_test_results(nrcell_id=nrcell_id, timeout=timeout)
        return res if raw else GetPuschCPCONFIGV1.from_object_dict(res)

    def get_5g_pucch_test_results(self, nrcell_id, timeout=60, raw=False):
        res = self.cp_config.get_5g_pucch_test_results(nrcell_id=nrcell_id, timeout=timeout)
        return res if raw else GetPucchCPCONFIGV1.from_object_dict(res)

    def get_5g_prach_test_results(self, nrcell_id, timeout=60, raw=False):
        res = self.cp_config.get_5g_prach_test_results(nrcell_id=nrcell_id, timeout=timeout)
        return res if raw else GetPrachCPCONFIGV1.from_object_dict(res)

    def get_running_test_models(self, timeout=30, raw=False):
        running_test_models = self.cp_config.get_running_test_models(timeout=timeout)

        if raw:
            return running_test_models

        return GetRunningTestModelsCPCONFIGV1.from_object_dict(running_test_models)

    def change_beam_pattern_id_downlink(self, nrcell_id, beam_pattern_id, timeout=10):
        return self.cp_config.change_beam_pattern_id_downlink(nrcell_id, beam_pattern_id, timeout=timeout)

    def change_beam_pattern_id_uplink(self, nrcell_id, beam_pattern_id, timeout=10):
        return self.cp_config.change_beam_pattern_id_uplink(nrcell_id, beam_pattern_id, timeout=timeout)

    def change_beam_pattern_id_performance(self, nrcell_id, beam_pattern_id, timeout=10):
        return self.cp_config.change_beam_pattern_id_performance(nrcell_id, beam_pattern_id, timeout=timeout)

    def get_managed_object_parameters_of_current_plan(self, dist_name, timeout=30):
        response = self.asm_v1.get_managed_object_parameters_of_current_plan(dist_name=dist_name, timeout=timeout)
        return ManagedObjectParameters.from_object_dict(response)
